using System.Diagnostics;

namespace VisualRelay.Tests;

/// <summary>
/// Shared git helpers extracted from the former GitCommitterTests partial class
/// so companion files can be promoted to independent parallel test classes.
/// </summary>
internal static class GitCommitterTestHelpers
{
    // ReSharper disable once AsyncMethodWithoutAwait — async kept so awaiting sites surface sync git failures via the awaited task.
    public static async Task InitGitRepo(string root)
    {
        Directory.CreateDirectory(Path.Combine(root, "src"));
        RunGit(root, "init");
        RunGit(root, "config user.email test@example.test");
        RunGit(root, "config user.name \"Test\"");
    }

    // ReSharper disable once AsyncMethodWithoutAwait — see InitGitRepo above.
    public static async Task StageAndCommitSeed(string root, string message)
    {
        RunGit(root, "add .");
        RunGit(root, $"commit -m \"{message}\"");
    }

    public static string RunGit(string rootPath, string arguments)
    {
        var startInfo = new ProcessStartInfo("/bin/sh", $"-c \"git -C '{rootPath}' {arguments}\"")
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false
        };
        // Strip DEVELOPER_DIR/SDKROOT so xcrun shim cannot resurrect a stale nix-store path inherited from the shell.
        startInfo.Environment.Remove("DEVELOPER_DIR");
        startInfo.Environment.Remove("SDKROOT");
        using var process = Process.Start(startInfo)!;
        var stdout = process.StandardOutput.ReadToEnd();
        var stderr = process.StandardError.ReadToEnd();
        process.WaitForExit();
        Assert.True(process.ExitCode == 0, stderr);
        return stdout;
    }

    /// <summary>Installs a commit-msg hook that rejects subjects matching <paramref name="rejectPattern"/>.</summary>
    public static void InstallRejectingCommitMsgHook(string repoRoot, string rejectPattern)
    {
        var hooksDir = Path.Combine(repoRoot, ".git", "hooks");
        Directory.CreateDirectory(hooksDir);
        var hookPath = Path.Combine(hooksDir, "commit-msg");
        File.WriteAllText(hookPath,
            $"#!/usr/bin/env bash{Environment.NewLine}" +
            $"set -euo pipefail{Environment.NewLine}" +
            $"subject=\"$(head -n 1 \"$1\")\"{Environment.NewLine}" +
            $"if echo \"$subject\" | grep -qE '{rejectPattern}'; then{Environment.NewLine}" +
            $"  echo \"hook: subject matches rejected pattern\" >&2{Environment.NewLine}" +
            $"  exit 1{Environment.NewLine}" +
            $"fi{Environment.NewLine}" +
            $"exit 0{Environment.NewLine}");
        if (!OperatingSystem.IsWindows())
        {
            File.SetUnixFileMode(hookPath,
                UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
        }
    }

    /// <summary>Installs a commit-msg hook that rejects every commit.</summary>
    public static void InstallRejectAllCommitMsgHook(string repoRoot)
    {
        var hooksDir = Path.Combine(repoRoot, ".git", "hooks");
        Directory.CreateDirectory(hooksDir);
        var hookPath = Path.Combine(hooksDir, "commit-msg");
        File.WriteAllText(hookPath,
            $"#!/usr/bin/env bash{Environment.NewLine}" +
            $"echo \"hook: all commits rejected\" >&2{Environment.NewLine}" +
            $"exit 1{Environment.NewLine}");
        if (!OperatingSystem.IsWindows())
        {
            File.SetUnixFileMode(hookPath,
                UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
        }
    }

    /// <summary>
    /// Installs a pre-commit hook mimicking the original Relay's commit-authority
    /// guard: it rejects the commit unless the RELAY_NONCE env var matches the nonce
    /// in .relay/ACTIVE/info.json.
    /// </summary>
    public static void InstallRelayNonceGuardHook(string repoRoot)
    {
        var hooksDir = Path.Combine(repoRoot, ".git", "hooks");
        Directory.CreateDirectory(hooksDir);
        var hookPath = Path.Combine(hooksDir, "pre-commit");
        File.WriteAllText(hookPath,
            """
            #!/usr/bin/env bash
            set -euo pipefail
            active=".relay/ACTIVE/info.json"
            [ -f "$active" ] || exit 0
            nonce="$(grep -o '"nonce"[[:space:]]*:[[:space:]]*"[^"]*"' "$active" | sed 's/.*"nonce"[[:space:]]*:[[:space:]]*"//; s/".*//' | head -1)"
            [ -z "$nonce" ] && exit 0
            if [ "${RELAY_NONCE:-}" = "$nonce" ]; then exit 0; fi
            echo "guard: RELAY_NONCE does not match active lock nonce" >&2
            exit 1
            """);
        if (!OperatingSystem.IsWindows())
        {
            File.SetUnixFileMode(hookPath,
                UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
        }
    }

    public static void WriteActiveInfo(string repoRoot, string nonce)
    {
        var activeDir = Path.Combine(repoRoot, ".relay", "ACTIVE");
        Directory.CreateDirectory(activeDir);
        File.WriteAllText(Path.Combine(activeDir, "info.json"),
            $"{{\"nonce\":\"{nonce}\"}}");
    }
}

using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

public sealed class GitCommitterCommitMsgHooksTests
{
    [Fact]
    public async Task CommitAsync_SetsRelayCommitTokenOnEveryAttempt()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "content");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");

        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "updated");

        // Install both hooks: pre-commit requires the token, commit-msg rejects
        // the first candidate. This proves the token is set on both attempts.
        RepoSetup.InstallPreCommitHook(repo.Root);
        GitCommitterTestHelpers.InstallRejectingCommitMsgHook(repo.Root, "\\.cs");

        // Write the ACTIVE/info.json so the pre-commit hook demands the token.
        var nonce = Guid.NewGuid().ToString("N");
        GitCommitterTestHelpers.WriteActiveInfo(repo.Root, nonce);

        var candidates = new[] { "fix(src): update app.cs", "fix: correct update logic" };
        var result = await GitCommitter.CommitAsync(
            repo.Root,
            "my-task",
            "abc123",
            candidates,
            ["src/app.cs"],
            [],
            commitToken: nonce,
            preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None);

        Assert.True(result.Success,
            "the second candidate should land; if it didn't, the token was missing on retry");
        var subject = GitCommitterTestHelpers.RunGit(repo.Root, "log -1 --pretty=%s");
        Assert.Equal("fix: correct update logic", subject.Trim());
    }

    [Fact]
    public async Task CommitAsync_SetsRelayNonce_SoOriginalRelayGuardAccepts()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "content");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");

        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "updated");

        // Mimic the original Relay's commit-authority guard (e.g. JobFinder's
        // .relay/hooks/pre-commit.ts): it rejects the commit unless the env var
        // RELAY_NONCE equals the active-lock nonce. Visual Relay must set RELAY_NONCE
        // (not only its own RELAY_COMMIT_TOKEN) or it can never land a sealed commit
        // in such a repo.
        var nonce = Guid.NewGuid().ToString("N");
        GitCommitterTestHelpers.WriteActiveInfo(repo.Root, nonce);
        GitCommitterTestHelpers.InstallRelayNonceGuardHook(repo.Root);

        var result = await GitCommitter.CommitAsync(
            repo.Root,
            "my-task",
            "abc123",
            ["feat: add widget"],
            ["src/app.cs"],
            [],
            commitToken: nonce,
            preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None);

        Assert.True(result.Success,
            "commit must pass a RELAY_NONCE-checking guard; if it didn't, GitCommitter isn't setting RELAY_NONCE");
    }
}

using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

/// <summary>
/// Regression tests for the in-run agent self-commit squash. When the swival
/// agent runs `git commit` itself mid-run (authorized via RELAY_COMMIT_TOKEN),
/// it lands a BARE provenance-less commit. The Commit stage must squash any
/// such commits made since run-start into the single sealed commit, so a task
/// is always exactly one sealed commit whose parent is the run-base.
/// </summary>
public sealed class GitCommitterRunBaseSquashTests
{
    // (b) One agent self-commit + further working-tree edits → one sealed commit.
    [Fact]
    public async Task CommitAsync_WithRunBase_SquashesAgentSelfCommitIntoOneSealedCommit()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // Agent self-commits the bulk implementation mid-run (bare, no trailers).
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "implemented");
        File.WriteAllText(Path.Combine(repo.Root, "src", "feature.cs"), "new feature");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip\"");

        // A further working-tree edit after the self-commit, not yet committed.
        File.WriteAllText(Path.Combine(repo.Root, "src", "extra.cs"), "extra");

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123",
            ["feat: add widget"], ["src/app.cs", "src/feature.cs", "src/extra.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");

        // Exactly ONE new commit on top of run-base: no bare commit remains.
        var countSinceBase = GitCommitterTestHelpers.RunGit(repo.Root, $"rev-list --count {runBase}..HEAD").Trim();
        Assert.Equal("1", countSinceBase);

        // That single commit's parent is the run-base.
        var parent = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD^").Trim();
        Assert.Equal(runBase, parent);

        // It is the sealed commit, carrying both trailers.
        var fullMessage = GitCommitterTestHelpers.RunGit(repo.Root, "log -1 --pretty=%B");
        Assert.Contains("Task: my-task", fullMessage);
        Assert.Contains("Relay-Seal: abc123", fullMessage);

        // Nothing is lost: the full task diff is present in the committed tree.
        Assert.Equal("implemented", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/app.cs"));
        Assert.Equal("new feature", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/feature.cs"));
        Assert.Equal("extra", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/extra.cs"));

        // Working tree is clean (everything committed).
        Assert.Equal(string.Empty, GitCommitterTestHelpers.RunGit(repo.Root, "status --porcelain").Trim());
    }

    // (b, plural) Several agent self-commits → all squashed into one sealed commit.
    [Fact]
    public async Task CommitAsync_WithRunBase_SquashesMultipleAgentSelfCommits()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        File.WriteAllText(Path.Combine(repo.Root, "src", "one.cs"), "1");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip 1\"");
        File.WriteAllText(Path.Combine(repo.Root, "src", "two.cs"), "2");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip 2\"");
        File.WriteAllText(Path.Combine(repo.Root, "src", "three.cs"), "3");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip 3\"");

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "seal999",
            ["feat: build three things"],
            ["src/one.cs", "src/two.cs", "src/three.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");
        Assert.Equal("1", GitCommitterTestHelpers.RunGit(repo.Root, $"rev-list --count {runBase}..HEAD").Trim());
        Assert.Equal(runBase, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD^").Trim());
        Assert.Contains("Relay-Seal: seal999", GitCommitterTestHelpers.RunGit(repo.Root, "log -1 --pretty=%B"));
        Assert.Equal("1", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/one.cs"));
        Assert.Equal("2", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/two.cs"));
        Assert.Equal("3", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/three.cs"));
    }

    // (a) No agent self-commit → unchanged: a single sealed commit on run-base.
    [Fact]
    public async Task CommitAsync_WithRunBase_NoSelfCommit_YieldsOneSealedCommit()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // Agent left only working-tree changes (no self-commit).
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "updated");

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123",
            ["feat: add widget"], ["src/app.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");
        Assert.Equal("1", GitCommitterTestHelpers.RunGit(repo.Root, $"rev-list --count {runBase}..HEAD").Trim());
        Assert.Equal(runBase, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD^").Trim());
        var fullMessage = GitCommitterTestHelpers.RunGit(repo.Root, "log -1 --pretty=%B");
        Assert.Contains("Task: my-task", fullMessage);
        Assert.Contains("Relay-Seal: abc123", fullMessage);
        Assert.Equal("updated", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/app.cs"));
    }

    // (c) Run-base several commits back (pre-existing history) is preserved;
    //     only the in-run agent commit is squashed, earlier history untouched.
    [Fact]
    public async Task CommitAsync_WithRunBase_PreservesEarlierHistory()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "v1");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "v2");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"chore: second\"");
        // Run starts here.
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();
        var rootCommit = GitCommitterTestHelpers.RunGit(repo.Root, "rev-list --max-parents=0 HEAD").Trim();

        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "v3");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"agent wip\"");

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123",
            ["feat: ship v3"], ["src/app.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");
        // One sealed commit on top of run-base.
        Assert.Equal("1", GitCommitterTestHelpers.RunGit(repo.Root, $"rev-list --count {runBase}..HEAD").Trim());
        Assert.Equal(runBase, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD^").Trim());
        // Earlier history is intact: root commit and run-base still reachable.
        Assert.Equal("3", GitCommitterTestHelpers.RunGit(repo.Root, "rev-list --count HEAD").Trim());
        Assert.Equal(rootCommit, GitCommitterTestHelpers.RunGit(repo.Root, "rev-list --max-parents=0 HEAD").Trim());
        Assert.Equal("v3", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/app.cs"));
    }

    // The deference path: the squash MUST keep the candidate-retry loop and a
    // target repo's commit-msg hook intact. With an agent self-commit present
    // AND a hook rejecting the first candidate, the second candidate must win,
    // still as a single sealed commit on the run-base.
    [Fact]
    public async Task CommitAsync_WithRunBase_HonoursCommitMsgHookAfterSquash()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "implemented");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip\"");

        GitCommitterTestHelpers.InstallRejectingCommitMsgHook(repo.Root, "\\.cs");

        var candidates = new[] { "fix(src): update app.cs logic", "fix: correct logic" };
        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123",
            candidates, ["src/app.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");
        Assert.Equal("1", GitCommitterTestHelpers.RunGit(repo.Root, $"rev-list --count {runBase}..HEAD").Trim());
        Assert.Equal("fix: correct logic", GitCommitterTestHelpers.RunGit(repo.Root, "log -1 --pretty=%s").Trim());
        Assert.Equal(runBase, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD^").Trim());
    }
}

using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

/// <summary>
/// Data-loss regression tests for the in-run squash. The plain squash
/// (GitCommitterRunBaseSquashTests) proves the happy path; these prove the
/// two adversarial cases an earlier review found could destroy committed work:
/// (1) a stale run-base whose <c>runBase..HEAD</c> range crosses ANOTHER task's
///     SEALED commit — the squash must NOT reset across it, or that sealed commit
///     (its work + its provenance) is folded into the wrong seal and lost;
/// (2) every candidate message rejected by a target-repo hook AFTER the soft-reset
///     already rewound HEAD — HEAD must be restored to its pre-squash value so the
///     agent's self-commit is reinstated, not silently dropped on the next reset.
/// </summary>
public sealed class GitCommitterRunBaseSquashGuardsTests
{
    // FIX 1 (CRITICAL): runBase..HEAD contains a SEALED commit (another task's
    // seal). The squash MUST be skipped — no reset — so the sealed commit and its
    // provenance survive. Better a cosmetic double-commit than a destroyed seal.
    [Fact]
    public async Task CommitAsync_WithRunBase_WhenRangeContainsSealedCommit_SkipsSquashAndPreservesSeal()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // A bare agent self-commit (could legitimately be squashed) ...
        File.WriteAllText(Path.Combine(repo.Root, "src", "early.cs"), "early");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip early\"");

        // ... then ANOTHER task's SEALED commit lands on top (carries Relay-Seal:).
        // This is the intervening committed work a stale run-base must never cross.
        File.WriteAllText(Path.Combine(repo.Root, "src", "other.cs"), "other-task");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        var sealMsgFile = Path.Combine(repo.Root, "seal-msg.txt");
        File.WriteAllText(sealMsgFile,
            "feat(other): another task's sealed work\n\nTask: other-task\nRelay-Seal: deadbeefcafe\n");
        GitCommitterTestHelpers.RunGit(repo.Root, $"commit -F '{sealMsgFile}'");
        File.Delete(sealMsgFile);
        var sealedSha = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // ... then a further bare self-commit on top of the seal.
        File.WriteAllText(Path.Combine(repo.Root, "src", "late.cs"), "late");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip late\"");
        var headBeforeCommit = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // A working-tree edit for the (stale-run-base) task we are now sealing.
        File.WriteAllText(Path.Combine(repo.Root, "src", "mine.cs"), "mine");

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "mytaskseal",
            ["feat: my task"], ["src/mine.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");

        // The squash was SKIPPED: HEAD's parent is the pre-existing tip
        // (headBeforeCommit), NOT the stale run-base. The reset never ran.
        Assert.Equal(headBeforeCommit, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD^").Trim());

        // The sealed commit is still reachable, byte-for-byte intact.
        var sealedReachable = GitCommitterTestHelpers.RunGit(repo.Root, $"merge-base --is-ancestor {sealedSha} HEAD; echo $?").Trim();
        Assert.Equal("0", sealedReachable);
        Assert.Contains("Relay-Seal: deadbeefcafe", GitCommitterTestHelpers.RunGit(repo.Root, $"log -1 --pretty=%B {sealedSha}"));
        Assert.Equal("other-task", GitCommitterTestHelpers.RunGit(repo.Root, $"show {sealedSha}:src/other.cs"));

        // The other task's content survives in HEAD's history (never rewound away).
        Assert.Equal("other-task", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/other.cs"));
    }

    // FIX 1 control: a range of ONLY bare self-commits (no Relay-Seal:) still
    // squashes — the guard must not over-fire and block the legitimate case.
    [Fact]
    public async Task CommitAsync_WithRunBase_WhenRangeIsOnlyBareCommits_SquashesNormally()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        File.WriteAllText(Path.Combine(repo.Root, "src", "one.cs"), "1");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip 1\"");
        File.WriteAllText(Path.Combine(repo.Root, "src", "two.cs"), "2");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip 2\"");

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "seal999",
            ["feat: build two things"], ["src/one.cs", "src/two.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");
        // Squash happened: exactly one sealed commit parented on the run-base.
        Assert.Equal("1", GitCommitterTestHelpers.RunGit(repo.Root, $"rev-list --count {runBase}..HEAD").Trim());
        Assert.Equal(runBase, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD^").Trim());
        Assert.Contains("Relay-Seal: seal999", GitCommitterTestHelpers.RunGit(repo.Root, "log -1 --pretty=%B"));
    }

    // FIX 2 (HIGH): the soft-reset succeeds, then EVERY candidate is rejected by a
    // commit-msg hook. CommitAsync must return Failed AND restore HEAD to its
    // pre-squash value so the agent's self-commit (and its work) is reinstated —
    // otherwise the next worktree reset discards the staged delta and it is lost.
    [Fact]
    public async Task CommitAsync_WithRunBase_WhenAllCandidatesRejectedAfterSquash_RestoresOrigHead()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // Agent self-commits the implementation mid-run (bare).
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "implemented");
        File.WriteAllText(Path.Combine(repo.Root, "src", "feature.cs"), "new feature");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip\"");
        var origHead = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // Target repo hook rejects EVERY candidate message.
        GitCommitterTestHelpers.InstallRejectAllCommitMsgHook(repo.Root);

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123",
            ["feat: add widget", "fix: alternative"], ["src/app.cs", "src/feature.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        // The commit failed (hook won) ...
        Assert.False(result.Success);
        Assert.NotNull(result.Error);
        Assert.Contains("commit rejected", result.Error);

        // ... but HEAD was rolled back to the pre-squash tip: the agent's
        // self-commit is BACK, nothing lost.
        Assert.Equal(origHead, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim());
        // The committed tree still carries the agent's work.
        Assert.Equal("implemented", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/app.cs"));
        Assert.Equal("new feature", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/feature.cs"));
        // And run-base did NOT become HEAD (would mean the rewind stuck).
        Assert.NotEqual(runBase, GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim());
    }

    // FIX 3 (MEDIUM): content that lives only in the rewound COMMITTED tree (here a
    // file added by an early self-commit, never present in the final working tree
    // because a later self-commit git-rm'd it... no — simpler: a file the agent
    // committed and then deleted from the WORKING TREE but NOT from the index path)
    // must not be dropped. We model the index-only case: a tracked file added in an
    // in-run commit whose working-tree copy is removed before the seal. It must
    // still land in the sealed commit (staged from the pre-reset tree).
    [Fact]
    public async Task CommitAsync_WithRunBase_PreservesCommittedOnlyContentAcrossSquash()
    {
        using var repo = TestRepository.Create();
        await GitCommitterTestHelpers.InitGitRepo(repo.Root);
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "base");
        await GitCommitterTestHelpers.StageAndCommitSeed(repo.Root, "chore: seed");
        var runBase = GitCommitterTestHelpers.RunGit(repo.Root, "rev-parse HEAD").Trim();

        // Agent commits a new generated file mid-run (it is in the committed tree).
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "implemented");
        File.WriteAllText(Path.Combine(repo.Root, "src", "generated.cs"), "gen");
        GitCommitterTestHelpers.RunGit(repo.Root, "add -A");
        GitCommitterTestHelpers.RunGit(repo.Root, "commit -m \"wip\"");

        // The agent then removes the file from the WORKING TREE only (e.g. a tool
        // cleaned a temp build artifact) WITHOUT staging the deletion — so it lives
        // only in the committed tree at squash time. With the run-base as the seal
        // parent, working-tree-only staging would drop it; staging from the
        // pre-reset tree keeps it.
        File.Delete(Path.Combine(repo.Root, "src", "generated.cs"));

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123",
            ["feat: add widget"], ["src/app.cs"], [],
            commitToken: null, preRunUntracked: null,
            tasksDir: null,
            CancellationToken.None, new GitInvoker(), runBaseSha: runBase);

        Assert.True(result.Success, $"Expected success, got: {result.Error}");
        Assert.Equal("1", GitCommitterTestHelpers.RunGit(repo.Root, $"rev-list --count {runBase}..HEAD").Trim());
        // The committed-only file survives the squash in the sealed commit.
        Assert.Equal("gen", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/generated.cs"));
        Assert.Equal("implemented", GitCommitterTestHelpers.RunGit(repo.Root, "show HEAD:src/app.cs"));
    }
}

