using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

public sealed class SwivalSubagentRunnerTimeoutTests
{
    [Fact]
    public async Task RunAsync_WhenSwivalExceedsTimeout_StopsAndReports()
    {
        using var repo = TestRepository.Create();
        var script = await SwivalTestHelpers.WriteExecutableAsync(
            repo.Root,
            "fake-swival-timeout",
            """
            #!/usr/bin/env bash
            # Simulate a hung process — sleep longer than the timeout.
            sleep 120
            """);
        var sink = new InMemoryRelayEventSink();
        var config = SwivalTestHelpers.Config(
            frontendTimeoutMs: 5_000,
            inactivityTimeoutMs: 30_000);
        var runner = new SwivalSubagentRunner(config, script, sink, SwivalTestHelpers.AlwaysReady,
            nonoBinary: await SwivalTestHelpers.WritePassthroughNonoAsync(repo.Root));

        var invocation = SwivalTestHelpers.Invocation(repo.Root);

        var sw = Stopwatch.StartNew();
        var result = await runner.RunAsync(invocation);
        sw.Stop();

        Assert.False(result.IsValid);
        Assert.Contains("timed out", result.Error, StringComparison.Ordinal);
        // Must not wait the full 120 s.
        Assert.True(sw.Elapsed.TotalSeconds < 15,
            $"timeout took {sw.Elapsed.TotalSeconds:F1}s, expected < 15s");
    }

    [Fact]
    public async Task RunAsync_WhenSwivalCompletesBeforeTimeout_ReturnsCleanly()
    {
        using var repo = TestRepository.Create();
        var script = await SwivalTestHelpers.WriteExecutableAsync(
            repo.Root,
            "fake-swival-quick",
            """
            #!/usr/bin/env bash
            sleep 0
            printf '```json\n{"findings":"quick check","constraints":[]}\n```\n'
            """);
        var sink = new InMemoryRelayEventSink();
        var config = SwivalTestHelpers.Config(
            frontendTimeoutMs: 30_000,
            inactivityTimeoutMs: 60_000);
        var runner = new SwivalSubagentRunner(config, script, sink, SwivalTestHelpers.AlwaysReady,
            nonoBinary: await SwivalTestHelpers.WritePassthroughNonoAsync(repo.Root));

        var invocation = SwivalTestHelpers.Invocation(repo.Root);

        var result = await runner.RunAsync(invocation);

        Assert.True(result.IsValid);
        Assert.Contains("quick check", result.RawText, StringComparison.Ordinal);
    }
}

