namespace VisualRelay.Tests;

public sealed class SwivalSubagentRunnerCommandFilterTests
{
    // ── ResolveCommandsOnPath unit tests ──────────────────────────────

    [Fact]
    public void ResolveCommandsOnPath_AllFound_ReturnsAll()
    {
        var resolved = SwivalSubagentRunner.ResolveCommandsOnPath(["ls", "echo"]);
        Assert.Equal(2, resolved.Found.Count);
        Assert.Empty(resolved.Missing);
    }

    [Fact]
    public void ResolveCommandsOnPath_SomeMissing_ReturnsPartial()
    {
        var bogus = Guid.NewGuid().ToString("N");
        var resolved = SwivalSubagentRunner.ResolveCommandsOnPath(["ls", bogus]);
        Assert.Equal(1, resolved.Found.Count);
        Assert.Single(resolved.Missing);
        Assert.Equal(bogus, resolved.Missing[0]);
    }

    [Fact]
    public void ResolveCommandsOnPath_AllMissing_ReturnsNone()
    {
        var bogusA = Guid.NewGuid().ToString("N");
        var bogusB = Guid.NewGuid().ToString("N");
        var resolved = SwivalSubagentRunner.ResolveCommandsOnPath([bogusA, bogusB]);
        Assert.Empty(resolved.Found);
        Assert.Equal(2, resolved.Missing.Count);
    }

    [Fact]
    public void ResolveCommandsOnPath_EmptyWhitelist_ReturnsEmpty()
    {
        var resolved = SwivalSubagentRunner.ResolveCommandsOnPath([]);
        Assert.Empty(resolved.Found);
        Assert.Empty(resolved.Missing);
    }

    [Fact]
    public void ResolveCommandsOnPath_TrimsAndSkipsBlanks()
    {
        var resolved = SwivalSubagentRunner.ResolveCommandsOnPath([" ls", "echo ", "  "]);
        Assert.Equal(2, resolved.Found.Count);
        Assert.Contains("ls", resolved.Found);
        Assert.Contains("echo", resolved.Found);
        Assert.Empty(resolved.Missing);
    }

    [Fact]
    public void ResolveCommandsOnPath_SingleCommaSeparatedArg_ReturnsAll()
    {
        // Pathological spacing — exactly what the comma-join guard must handle.
        var resolved = SwivalSubagentRunner.ResolveCommandsOnPath(
            "git , ls ,   cat ,,echo".Split(','));
        Assert.Equal(4, resolved.Found.Count);
        Assert.Contains("git", resolved.Found);
        Assert.Contains("ls", resolved.Found);
        Assert.Contains("cat", resolved.Found);
        Assert.Contains("echo", resolved.Found);
        Assert.Empty(resolved.Missing);
    }

    // ── DropEvent hook tests ──────────────────────────────────────────

    [Fact]
    public async Task RunAsync_DropEvent_Fires_WhenCommandMissing()
    {
        using var repo = TestRepository.Create();
        var bogus = Guid.NewGuid().ToString("N");
        var script = await SwivalTestHelpers.WriteExecutableAsync(
            repo.Root,
            "fake-swival-drop-event",
            """
            #!/usr/bin/env bash
            printf '```json\n{"findings":"nothing","constraints":[]}\n```\n'
            """);
        var sink = new InMemoryRelayEventSink();
        var config = SwivalTestHelpers.TestConfig();
        var runner = new SwivalSubagentRunner(config, script, sink, SwivalTestHelpers.AlwaysReady,
            nonoBinary: await SwivalTestHelpers.WritePassthroughNonoAsync(repo.Root));
        var stage = new RelayStageDefinition(
            2, "Research", "cheap", "llm", "some",
            $"git,{bogus}",
            "Investigate the codebase.",
            """{ "findings": string, "constraints": string[] }""");
        var invocation = SwivalTestHelpers.Invocation(repo.Root) with { Stage = stage };

        var result = await runner.RunAsync(invocation);
        Assert.True(result.IsValid);

        Assert.Contains(sink.Events, e =>
            e is { EventName: "command_dropped", Data: not null } &&
            e.Data.TryGetValue("name", out var name) &&
            name == bogus);
    }

    [Fact]
    public async Task RunAsync_NoDropEvent_WhenAllCommandsPresent()
    {
        using var repo = TestRepository.Create();
        var script = await SwivalTestHelpers.WriteExecutableAsync(
            repo.Root,
            "fake-swival-clean",
            """
            #!/usr/bin/env bash
            printf '```json\n{"findings":"nothing","constraints":[]}\n```\n'
            """);
        var sink = new InMemoryRelayEventSink();
        var config = SwivalTestHelpers.TestConfig();
        var runner = new SwivalSubagentRunner(config, script, sink, SwivalTestHelpers.AlwaysReady,
            nonoBinary: await SwivalTestHelpers.WritePassthroughNonoAsync(repo.Root));
        var invocation = SwivalTestHelpers.Invocation(repo.Root);

        var result = await runner.RunAsync(invocation);
        Assert.True(result.IsValid);
        Assert.DoesNotContain(sink.Events, e => e.EventName == "command_dropped");
    }
}

