    // ── Manifest authority ──────────────────────────────────────────

    [Fact]
    public async Task Driver_ManifestOverridesAutoInclude_LowerNewFileNotInManifest_IsNOTCommitted()
    {
        // When the stage-4 manifest explicitly lists only a subset of
        // authored files, auto-include must NOT add the unlisted ones.
        // Manifest authority is the contract: if the agent lists a file
        // set, the commit must be exactly that set (plus .relay).
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteTask("manifest-authority",
            "# Manifest authority\n");

        Directory.CreateDirectory(Path.Combine(repo.Root, "src"));
        File.WriteAllText(Path.Combine(repo.Root, "src", "app.cs"), "old");
        TestGit.Run(repo.Root, "init");
        TestGit.Run(repo.Root, "config", "user.email",
            "visual-relay@test.example");
        TestGit.Run(repo.Root, "config", "user.name", "VR Tests");
        TestGit.Run(repo.Root, "add", ".");
        TestGit.Run(repo.Root, "commit", "-m", "chore: seed");

        var runner = new ManifestAuthoritySubagentRunner();
        var driver = new RelayDriver(
            RelayDriverDependencies.ForTests(runner,
                new ScriptedTestRunner(
                    new TestRunResult(1, "red"),
                    new TestRunResult(0, "green")),
                new InMemoryRelayEventSink()),
            new RelayDriverOptions(CreateGitCommit: true));

        var outcome = await driver.RunTaskAsync(repo.Root,
            "manifest-authority");
        Assert.Equal(RelayTaskOutcomeStatus.Committed, outcome.Status);

        var committed = TestGit.Run(repo.Root, "show", "--name-only",
            "--pretty=format:", "HEAD");
        Assert.Contains("src/app.cs", committed);
        // The extra file NOT in the manifest must NOT be committed.
        Assert.DoesNotContain("src/extra.cs", committed);
    }
}

    // ── Manifest authority ──────────────────────────────────────────

    [Fact]
    public async Task TwoTasks_ManifestAuthority_EnforcedAcrossPlanExecuteSplit()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteTask("clean", "# Clean\n");
        repo.WriteTask("mixed", "# Mixed manifest\n");

        Directory.CreateDirectory(Path.Combine(repo.Root, "src"));
        File.WriteAllText(Path.Combine(repo.Root, "src", "shared.cs"), "baseline");
        TestGit.Run(repo.Root, "init");
        TestGit.Run(repo.Root, "config", "user.email", "test@example.test");
        TestGit.Run(repo.Root, "config", "user.name", "Test");
        TestGit.Run(repo.Root, "add", ".");
        TestGit.Run(repo.Root, "commit", "-m", "seed");

        var cleanInner = new ScriptedSubagentRunner();
        cleanInner.SeedHappyPath("src/clean.cs", "tests/clean.tests.cs");
        var cleanRunner = new FileWritingSubagentRunner(cleanInner, 6, "src/clean.cs", "clean impl");

        var mixedRunner = new FileWritingSubagentRunner(
            new BadManifestSubagentRunner(), 6, "src/real.cs", "real impl");

        var config = new RelayConfig(
            TasksDir: "llm-tasks",
            TestCommand: "dotnet test",
            TestFileCommand: "dotnet test {files}",
            LogSources: [],
            TierProfiles: new Dictionary<string, string>(),
            EnableFixVerify: true,
            MaxStageFailures: 3,
            MaxTurns: 200,
